        if (resolver instanceof AbstractMessageConverterMethodArgumentResolver) {
            found = true;
            AbstractMessageConverterMethodArgumentResolver processor = (AbstractMessageConverterMethodArgumentResolver) resolver;
            List<HttpMessageConverter<?>> converters = (List<HttpMessageConverter<?>>) ReflectionTestUtils.getField(processor, "messageConverters");
            assertMediaTypeSupported(converters, mediaType, RepresentationModel.class);
