    verifyCreatingNewEntityReactivelyShouldWork(MediaTypes.HAL_JSON);
    verifyCreatingNewEntityWorks(MediaTypes.HAL_FORMS_JSON);
    verifyCreatingNewEntityReactivelyShouldWork(MediaTypes.HAL_FORMS_JSON);
}
